+                        if (vSpent[i].IsNull())
+                        {
+                            pairTx.second = false;
+                            break;
+                        }
+                        pairTx.first[i] = false;
+                    }
+                }
+
+                if (pairTx.second == false)
+                    continue;
+
+                pairTx.first[txout.n] = true;
+            }
+        }
+
+        pindexScan = pindexScan->pnext;
+    }
+
